using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BDInspect {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_B2_Circular.unity");var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork");var h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_DetailMezzanine"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true));File.WriteAllText(h+"/before.json",JsonConvert.SerializeObject(all.Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),t.name,position=new[]{t.position.x,t.position.y,t.position.z},active=t.gameObject.activeSelf}),Formatting.Indented));return new{roots=s.GetRootGameObjects().Select(g=>g.name).ToArray(),corridors=root.transform.Find("B2_PipeCorridors").Cast<Transform>().Select(t=>new{t.name,children=t.Cast<Transform>().Select(c=>c.name).ToArray()}).Take(1).ToArray(),objects=all.Count()};}
}
